CREATE TABLE studio_settings(id INTEGER PRIMARY KEY CHECK(id=1),data TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL);
INSERT INTO studio_settings VALUES(1,'{}',datetime('now'));
CREATE TABLE studio_content(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('series','blog','template')),slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,data TEXT NOT NULL,is_published INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE academy_credentials(profile_id TEXT PRIMARY KEY REFERENCES academy_profiles(id) ON DELETE CASCADE,slug TEXT NOT NULL UNIQUE,university TEXT NOT NULL DEFAULT '',experience INTEGER NOT NULL DEFAULT 0,language TEXT NOT NULL DEFAULT 'en',verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE delivery_review(recording_id TEXT PRIMARY KEY REFERENCES delivery_recordings(id) ON DELETE CASCADE,state TEXT NOT NULL DEFAULT 'in_review' CHECK(state IN ('in_review','changes_requested','approved','delivered')),approved_at TEXT,approved_by TEXT,chapters TEXT NOT NULL DEFAULT '[]',watermark INTEGER NOT NULL DEFAULT 0,poster_key TEXT);
CREATE TABLE delivery_notes(id TEXT PRIMARY KEY,recording_id TEXT NOT NULL REFERENCES delivery_recordings(id) ON DELETE CASCADE,actor TEXT NOT NULL,actor_name TEXT NOT NULL,second REAL NOT NULL CHECK(second>=0),note TEXT NOT NULL,resolved INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE delivery_activity(id TEXT PRIMARY KEY,recording_id TEXT NOT NULL REFERENCES delivery_recordings(id) ON DELETE CASCADE,actor TEXT NOT NULL,actor_name TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE INDEX delivery_activity_recording ON delivery_activity(recording_id,created_at);
CREATE TABLE delivery_progress(recording_id TEXT NOT NULL REFERENCES delivery_recordings(id) ON DELETE CASCADE,actor TEXT NOT NULL,second REAL NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,PRIMARY KEY(recording_id,actor));
CREATE TABLE delivery_variants(recording_id TEXT NOT NULL REFERENCES delivery_recordings(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('compressed','audio')),asset_id TEXT NOT NULL UNIQUE REFERENCES delivery_recordings(id) ON DELETE CASCADE,PRIMARY KEY(recording_id,kind));
CREATE TABLE delivery_captions(recording_id TEXT NOT NULL REFERENCES delivery_recordings(id) ON DELETE CASCADE,language TEXT NOT NULL CHECK(language IN ('ar','en')),vtt TEXT NOT NULL,transcript TEXT NOT NULL,reviewed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(recording_id,language));
CREATE TABLE delivery_links(id TEXT PRIMARY KEY,recording_id TEXT NOT NULL REFERENCES delivery_recordings(id) ON DELETE CASCADE,label TEXT NOT NULL,password TEXT NOT NULL,expires_at INTEGER NOT NULL,max_views INTEGER NOT NULL CHECK(max_views>0),views INTEGER NOT NULL DEFAULT 0,revoked INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE delivery_link_sessions(token_hash TEXT PRIMARY KEY,link_id TEXT NOT NULL REFERENCES delivery_links(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE studio_requests(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,data TEXT NOT NULL,start_time TEXT,end_time TEXT,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','declined')),appointment_id INTEGER REFERENCES scheduling_appointment(id),created_at TEXT NOT NULL);
CREATE TABLE studio_checklists(appointment_id INTEGER PRIMARY KEY REFERENCES scheduling_appointment(id) ON DELETE CASCADE,data TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE studio_contacts(client_id INTEGER PRIMARY KEY REFERENCES accounts_client(id) ON DELETE CASCADE,email TEXT NOT NULL DEFAULT '',consent INTEGER NOT NULL DEFAULT 0);
CREATE TABLE studio_outbox(id TEXT PRIMARY KEY,dedupe TEXT NOT NULL UNIQUE,client_id INTEGER REFERENCES accounts_client(id),subject TEXT NOT NULL,message TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sending','sent','failed','manual','cancelled')),attempts INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,sent_at TEXT);
